import{_ as r,C as d,o as g,c as e,j as n,a as h,E as o,a2 as a}from"./chunks/framework.D6ZvhnGC.js";const P=JSON.parse('{"title":"3. Luật & cơ chế","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/rules.md","filePath":"gdd/rules.md"}'),c={name:"gdd/rules.md"},l={id:"_3-1-thang-va-thua",tabindex:"-1"},s={id:"_3-2-board-va-đoi-hinh",tabindex:"-1"},m={id:"_3-3-may-bay",tabindex:"-1"},b={id:"_3-4-sinh-may-bay-cho-mot-man",tabindex:"-1"},u={id:"_3-5-may-bay-an",tabindex:"-1"},p={id:"_3-6-may-bay-noi-đoi",tabindex:"-1"},y={id:"_3-7-khoi-lon",tabindex:"-1"};function v(k,t,T,_,x,S){const i=d("Badge");return g(),e("div",null,[t[21]||(t[21]=n("h1",{id:"_3-luat-co-che",tabindex:"-1"},[h("3. Luật & cơ chế "),n("a",{class:"header-anchor",href:"#_3-luat-co-che","aria-label":'Permalink to "3. Luật & cơ chế"'},"​")],-1)),t[22]||(t[22]=n("p",null,[h("Mọi hằng số nằm ở "),n("code",null,"src/game/data.ts"),h(", logic ở "),n("code",null,"src/scenes/Game.ts"),h(".")],-1)),n("h2",l,[t[0]||(t[0]=h("3.1 Thắng và thua ",-1)),o(i,{type:"tip",text:"Live"}),t[1]||(t[1]=h()),t[2]||(t[2]=n("a",{class:"header-anchor",href:"#_3-1-thang-va-thua","aria-label":'Permalink to "3.1 Thắng và thua <Badge type="tip" text="Live" />"'},"​",-1))]),t[23]||(t[23]=a('<table tabindex="0"><thead><tr><th></th><th>Điều kiện</th><th>Sau đó</th></tr></thead><tbody><tr><td><strong>Thắng</strong></td><td>Số khối còn lại về 0 (tính cả độ bền khối lớn).</td><td>0.7 s sau hiện popup <strong>HOÀN THÀNH!</strong> → <em>Màn tiếp theo</em> (màn 10 → <em>Chơi lại từ đầu</em>).</td></tr><tr><td><strong>Thua</strong></td><td>Đồng hồ bế tắc đạt <strong>5 s</strong> (<code>STALL_MAX</code>).</td><td>0.9 s sau hiện popup <strong>BẾ TẮC!</strong> → <em>Thử lại</em> màn đó.</td></tr></tbody></table><p><strong>Đồng hồ bế tắc</strong> chỉ chạy khi trên board có ít nhất một khối bắn được, và một trong hai điều sau đúng:</p><ul><li>vùng chiến đấu <strong>đầy 5 máy bay</strong>, hoặc</li><li>có ít nhất một máy bay đang bay nhưng <strong>không có gì xảy ra được</strong>: không còn viên đạn nào đang bay, không máy bay nào trên trời có mục tiêu, và không cất cánh được chiếc nào bắn được ngay (kể cả vì cặp nối đôi chưa đủ điều kiện).</li></ul><p>Mỗi khối bị phá (hoặc trừ độ bền) đặt đồng hồ về 0. Khi board trống tạm thời vì mảng sau đang trôi vào, đồng hồ không chạy. Lúc còn 3, 2, 1 giây máy rung nhẹ.</p><p>Khi chưa có máy bay nào trên trời thì không bao giờ thua: người chơi luôn có thể cho bay một chiếc lên (nó sẽ đứng chờ).</p>',5)),n("h2",s,[t[3]||(t[3]=h("3.2 Board và đội hình ",-1)),o(i,{type:"tip",text:"Live"}),t[4]||(t[4]=h()),t[5]||(t[5]=n("a",{class:"header-anchor",href:"#_3-2-board-va-đoi-hinh","aria-label":'Permalink to "3.2 Board và đội hình <Badge type="tip" text="Live" />"'},"​",-1))]),t[24]||(t[24]=a('<table tabindex="0"><thead><tr><th>Thông số</th><th>Giá trị</th></tr></thead><tbody><tr><td>Bề ngang board</td><td>21 cột (<code>BCOLS</code>)</td></tr><tr><td>Số hàng khối hiển thị</td><td>10 (<code>BROWS</code>) + 2 hàng trống phía dưới (<code>GAP</code>)</td></tr><tr><td>Cỡ ô</td><td><code>floor(min((450 − 40) / 21, chiều cao tranh / 12))</code> = <strong>19 px</strong> với layout hiện tại</td></tr><tr><td>Căn ngang</td><td>Toàn bộ đội hình được căn giữa theo 21 cột, bất kể <code>ox</code> viết trong dữ liệu màn</td></tr></tbody></table><p>Khối <strong>không tự trôi</strong>. Khi hàng thấp nhất còn khối bị phá sạch, cả đội hình bước xuống cho tới khi khối thấp nhất lại nằm ở hàng 10, với tốc độ 6 hàng/giây (mượt chứ không nhảy). Đầu màn, đội hình được đặt sao cho khối thấp nhất nằm ngay hàng 10.</p><p><strong>Khối lộ ra</strong> của một cột là khối thấp nhất trong cột đó, xét mọi mảng hình. Khối đã có đủ đạn đang bay tới (số viên ≥ độ bền) được bỏ qua, nên khối ngay phía trên trở thành mục tiêu kế tiếp. Khối còn nằm phía trên mép board thì chưa bắn được.</p>',3)),n("h2",m,[t[6]||(t[6]=h("3.3 Máy bay ",-1)),o(i,{type:"tip",text:"Live"}),t[7]||(t[7]=h()),t[8]||(t[8]=n("a",{class:"header-anchor",href:"#_3-3-may-bay","aria-label":'Permalink to "3.3 Máy bay <Badge type="tip" text="Live" />"'},"​",-1))]),t[25]||(t[25]=a('<h3 id="cat-canh" tabindex="-1">Cất cánh <a class="header-anchor" href="#cat-canh" aria-label="Permalink to &quot;Cất cánh&quot;">​</a></h3><ul><li>Chạm vào khoang chứa (vùng dưới cùng, chia 3 cột đều nhau) để cho máy bay đầu hàng cất cánh vào chỗ trống đầu tiên.</li><li>Vùng chiến đấu có <strong>5 chỗ</strong> (<code>SLOTS</code>), xếp so le cao thấp.</li><li>Khoang trống → toast <em>Khoang này đã hết máy bay</em>. Đã đủ 5 → toast <em>Vùng chiến đấu đã đầy 5 máy bay!</em></li></ul><h3 id="hanh-vi-tu-đong" tabindex="-1">Hành vi tự động <a class="header-anchor" href="#hanh-vi-tu-đong" aria-label="Permalink to &quot;Hành vi tự động&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Trạng thái</th><th>Hành vi</th></tr></thead><tbody><tr><td><code>enter</code></td><td>Bay từ khoang chứa vào chỗ của mình.</td></tr><tr><td><code>idle</code></td><td>Có khối cùng màu đang lộ ra → nhắm khối <strong>thấp nhất</strong>, bằng nhau thì lấy <strong>bên trái</strong>. Không có → đứng chờ, vẫn giữ chỗ; sau 1.2 s chờ thì lắc nhẹ và nhấp nháy.</td></tr><tr><td><code>attack</code></td><td>Bay ngang tới cột mục tiêu, cách tâm cột dưới 4 px thì bắn. Bắn xong nhắm luôn mục tiêu kế tiếp để không bị kéo về chỗ.</td></tr><tr><td><code>leave</code></td><td>Hết đạn, hoặc màu của nó đã sạch khỏi tranh → nhả chỗ, bay xuống 430 px/s và mờ dần.</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Thông số</th><th>Giá trị</th></tr></thead><tbody><tr><td>Hồi giữa hai phát</td><td>0.16 s (<code>FIRE_CD</code>)</td></tr><tr><td>Tốc độ đạn</td><td>900 px/s (<code>BULLET_V</code>)</td></tr><tr><td>Bám mục tiêu</td><td>nội suy <code>min(1, dt × 7)</code> mỗi frame (khi chờ: <code>dt × 1.3</code>)</td></tr><tr><td>Đạn trúng</td><td>khi đầu đạn chạm 55% chiều cao ô mục tiêu; vị trí tính lại mỗi frame vì đội hình có thể đang trượt</td></tr></tbody></table><h3 id="tang-toc-×2" tabindex="-1">Tăng tốc ×2 <a class="header-anchor" href="#tang-toc-×2" aria-label="Permalink to &quot;Tăng tốc ×2&quot;">​</a></h3><p>Khi cả ba khoang chứa đều trống, mọi máy bay còn lại di chuyển, bắn và rời đi <strong>nhanh gấp đôi</strong>. Vùng chiến đấu hiện chữ <em>TĂNG TỐC ×2</em>.</p>',7)),n("h2",b,[t[9]||(t[9]=h("3.4 Sinh máy bay cho một màn ",-1)),o(i,{type:"tip",text:"Live"}),t[10]||(t[10]=h()),t[11]||(t[11]=n("a",{class:"header-anchor",href:"#_3-4-sinh-may-bay-cho-mot-man","aria-label":'Permalink to "3.4 Sinh máy bay cho một màn <Badge type="tip" text="Live" />"'},"​",-1))]),t[26]||(t[26]=a("<ol><li><p><strong>Mô phỏng thứ tự phá khối</strong>: trên một bản sao board, lặp lại &quot;phá khối lộ ra thấp nhất (bằng nhau lấy bên trái)&quot; cho tới hết. Kết quả là thứ tự màu sẽ xuất hiện.</p></li><li><p><strong>Chia đạn theo màu</strong>: số khối của mỗi màu được chia thành các máy bay <strong>10–20 viên</strong>, tổng đúng bằng số khối:</p><ul><li>còn ≥ 30 → tách một chiếc 20;</li><li>còn 10–20 → một chiếc đúng bằng phần còn lại;</li><li>còn 21–29 → hai chiếc (n − 10) và 10.</li></ul><p>Ví dụ: 25 → 15 + 10, 33 → 20 + 13, 48 → 20 + 18 + 10.</p></li><li><p><strong>Sắp thứ tự</strong>: mỗi máy bay lấy vị trí khối đầu tiên nó phụ trách trong thứ tự ở bước 1; xếp tăng dần, rồi mỗi cặp liền kề có <strong>30%</strong> bị đổi chỗ để bớt đoán trước.</p></li><li><p><strong>Chia vào 3 khoang</strong> lần lượt (chiếc thứ j vào khoang <code>j mod 3</code>).</p></li></ol><p>Khi một màu đã sạch khỏi tranh, mọi máy bay màu đó còn trong khoang bị bỏ đi.</p>",2)),n("h2",u,[t[12]||(t[12]=h("3.5 Máy bay ẩn ",-1)),o(i,{type:"tip",text:"Live"}),t[13]||(t[13]=h()),t[14]||(t[14]=n("a",{class:"header-anchor",href:"#_3-5-may-bay-an","aria-label":'Permalink to "3.5 Máy bay ẩn <Badge type="tip" text="Live" />"'},"​",-1))]),t[27]||(t[27]=n("p",null,[h("Ở màn có "),n("code",null,"hidden"),h(", mỗi máy bay "),n("strong",null,"không đứng đầu"),h(" khoang lúc bắt đầu màn có xác suất "),n("code",null,"hidden"),h(" bị ẩn: hiện màu xám "),n("code",null,"#4b5578"),h(" và số đạn "),n("code",null,"?"),h(". Khi lên đầu hàng nó lộ màu thật, có một vòng sáng loé lên trong 0.5 s và máy rung nhẹ. Máy bay thuộc cặp nối đôi không bao giờ bị ẩn.")],-1)),n("h2",p,[t[15]||(t[15]=h("3.6 Máy bay nối đôi ",-1)),o(i,{type:"tip",text:"Live"}),t[16]||(t[16]=h()),t[17]||(t[17]=n("a",{class:"header-anchor",href:"#_3-6-may-bay-noi-đoi","aria-label":'Permalink to "3.6 Máy bay nối đôi <Badge type="tip" text="Live" />"'},"​",-1))]),t[28]||(t[28]=a("<p>Ở màn có <code>connected = N</code>, tạo tối đa N cặp. Cặp thứ n nằm ở khoang <code>(2n) mod 3</code> và <code>(2n + 1) mod 3</code>, cùng độ sâu n trong hàng; chiếc thứ hai được chọn sao cho <strong>khác màu</strong> và <strong>số đạn gần nhất</strong> với chiếc thứ nhất.</p><ul><li>Hai chiếc chỉ cất cánh <strong>cùng nhau</strong>: cả hai phải đứng đầu khoang của mình (hoặc chiếc kia đứng ngay sau trong cùng khoang) <strong>và</strong> còn ít nhất <strong>2 chỗ trống</strong>.</li><li>Thiếu điều kiện → toast <em>Cặp nối đôi: chiếc còn lại chưa lên đầu hàng</em> hoặc <em>Cặp nối đôi cần 2 chỗ trống</em>.</li><li>Lên tới vùng chiến đấu thì hai chiếc hoạt động độc lập.</li><li>Trong khoang, chiếc thuộc cặp có vòng vàng; hai chiếc cùng cặp được nối bằng dây vàng nét đứt.</li></ul>",2)),n("h2",y,[t[18]||(t[18]=h("3.7 Khối lớn ",-1)),o(i,{type:"tip",text:"Live"}),t[19]||(t[19]=h()),t[20]||(t[20]=n("a",{class:"header-anchor",href:"#_3-7-khoi-lon","aria-label":'Permalink to "3.7 Khối lớn <Badge type="tip" text="Live" />"'},"​",-1))]),t[29]||(t[29]=a('<p>Ở màn có <code>big</code>, trên <strong>mỗi mảng hình</strong> thử đặt <code>n</code> khối lớn:</p><table tabindex="0"><thead><tr><th>Độ bền</th><th>Kích thước</th></tr></thead><tbody><tr><td>5–6</td><td>2 × 2</td></tr><tr><td>7–8</td><td>3 × 3</td></tr><tr><td>9–10</td><td>4 × 4</td></tr><tr><td><code>size</code> ghi rõ trong dữ liệu (lõi trùm)</td><td>5 × 5</td></tr></tbody></table><ul><li>Độ bền chọn ngẫu nhiên đều trong khoảng <code>hp</code> của màn.</li><li>Vị trí: thử tối đa 120 ô vuông ngẫu nhiên, chỉ nhận vùng đã kín khối và chưa có khối lớn. Ưu tiên vùng mà một màu chiếm ≥ 60%; khối lớn mang màu chiếm đa số.</li><li>Không được làm màu nào còn lại 1–9 khối (vì máy bay mang ít nhất 10 viên).</li><li>Mỗi phát trúng trừ 1 độ bền và loé sáng; về 0 thì vỡ cả vùng (90 mảnh vỡ, rung mạnh hơn). Khối lớn chắn mọi cột nó phủ.</li></ul><p>Vì vị trí và độ bền là ngẫu nhiên, tổng số khối của màn có khối lớn thay đổi mỗi lần chơi (xem <a href="./levels">Màn chơi</a>).</p>',4))])}const L=r(c,[["render",v]]);export{P as __pageData,L as default};
